import{_ as i,H as p,f as t,i as l}from"./chunks/framework.BH2BK_3i.js";const A=JSON.parse('{"title":"02 | 设计是传递、放大企业产品价值的必要方法","description":"","frontmatter":{},"headers":[{"level":2,"title":"体验设计对 B 端产品有什么样的价值？","slug":"体验设计对-b-端产品有什么样的价值","link":"#体验设计对-b-端产品有什么样的价值","children":[]},{"level":2,"title":"以 5D 产品设计体系传递产品的价值","slug":"以-5d-产品设计体系传递产品的价值","link":"#以-5d-产品设计体系传递产品的价值","children":[{"level":3,"title":"什么是“以客户为中心”？","slug":"什么是-以客户为中心","link":"#什么是-以客户为中心","children":[]},{"level":3,"title":"为什么所有事都该看作一件事？","slug":"为什么所有事都该看作一件事","link":"#为什么所有事都该看作一件事","children":[]},{"level":3,"title":"5D 产品设计体系","slug":"_5d-产品设计体系","link":"#_5d-产品设计体系","children":[]}]},{"level":2,"title":"B 端设计师的核心能力进阶","slug":"b-端设计师的核心能力进阶","link":"#b-端设计师的核心能力进阶","children":[]},{"level":2,"title":"总结时刻","slug":"总结时刻","link":"#总结时刻","children":[]},{"level":2,"title":"解惑 ToB 体验设计","slug":"解惑-tob-体验设计","link":"#解惑-tob-体验设计","children":[]}],"relativePath":"B端体验设计入门课/02｜设计是传递、放大企业产品价值的必要方法.md","filePath":"B端体验设计入门课/02｜设计是传递、放大企业产品价值的必要方法.md","lastUpdated":1795453896000}'),a={name:"B端体验设计入门课/02｜设计是传递、放大企业产品价值的必要方法.md"};function n(s,e,o,r,E,h){return p(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="_02-设计是传递、放大企业产品价值的必要方法" tabindex="-1">02 | 设计是传递、放大企业产品价值的必要方法 <a class="header-anchor" href="#_02-设计是传递、放大企业产品价值的必要方法" aria-label="Permalink to &quot;02 | 设计是传递、放大企业产品价值的必要方法&quot;">​</a></h1><p>你好，我是汤圆。今天将给你分享 B 端体验设计中有效的思维模型。</p><p>相信你初识 B 端的时候，也会觉得 B 端产品的体验设计过程非常地混乱。不管是做功能规划，还是做具体界面的体验设计，都会经常被客户的需求搞得晕头转向。</p><p>而且 B 端的研发时间相对要长一些，有些产品需要 1 个月，有些甚至需要 2-3 个月，这导致了研发过程中经常发生需求变更，从而让产品研发成本更高，耗时更长。</p><p>其实，这些都是因为你没有找到合适 B 端的设计步骤。</p><p>这节课，我会和你分享我总结的 B 端设计“5D 模型”：信息洞察（Discover）、需求定义（Define）、功能架构（Design）、研发落地（Development）、体验迭代（Update）。但是，在开始之前，我希望你先重新理解体验设计对于 B 端产品的价值，我认为这是 5D 设计模型对 B端体验设计有效的基础背景。</p><h2 id="体验设计对-b-端产品有什么样的价值" tabindex="-1">体验设计对 B 端产品有什么样的价值？ <a class="header-anchor" href="#体验设计对-b-端产品有什么样的价值" aria-label="Permalink to &quot;体验设计对 B 端产品有什么样的价值？&quot;">​</a></h2><p>在以前，大部分人认为体验是可有可无的，而很多从事体验设计相关工作的人，也都不太清楚自己在企业中的商业价值，所以导致了体验设计这件事一直只被口头重视，但落实得并不好。</p><p>这里，我给你分享下我认为体验设计以及设计本身对于企业非常重要的价值是什么。</p><p>我的观点：设计是传递、甚至放大企业产品或服务价值的必要方法。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/B%E7%AB%AF%E4%BD%93%E9%AA%8C%E8%AE%BE%E8%AE%A1%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/1.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/B%E7%AB%AF%E4%BD%93%E9%AA%8C%E8%AE%BE%E8%AE%A1%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/1.jpeg" alt=""></a></p><p>这里有两个要素，客户和产品。我从供需关系的角度来给你分析。</p><p>先看需求侧。客户永远都会购买一个自己认为“高性价比”的产品，而这个高性价比是主观的。你认为 iPhone 质量很好，一个手机可以用 6、7 年，那么 6000 元对你来说就是便宜的；你认为小米价格低，质量也不错，那么 3000 元的小米对你来说也是最便宜的。</p><p>你会发现，不同的人评判价值的标准并不一样，有很多时候都是主观的。所以，设计师必须能清楚地洞察到客户心中主观的感受是什么。</p><p>再来看供给侧，就是制造 B 端产品的企业。所有的企业都追求一件事：以更低的成本生产，以更高的价格出售。而正直的企业会通过不断地生产客户主观认为有需求、特别喜爱的产品来实现这个目标。</p><p>但是，在客户与产品之间，存在一条鸿沟。这条鸿沟是产品虽然花费了大量的成本制作，质量也非常好，但客户没有在使用或互动的过程中感受到，那么这个产品在客户眼中就是没有价值。所以这个过程，就必须要进行一个处理。处理的目标就是让客户更好地感知到产品的价值，让产品真实的价值与客户的感知匹配，我们通常就把这个过程称为“设计”。</p><p>所以，我认为，设计的目标就是传递甚至部分放大客户对于产品的主观价值感知。而 B 端产品中，对于体验的设计就是最重要的工作。</p><h2 id="以-5d-产品设计体系传递产品的价值" tabindex="-1">以 5D 产品设计体系传递产品的价值 <a class="header-anchor" href="#以-5d-产品设计体系传递产品的价值" aria-label="Permalink to &quot;以 5D 产品设计体系传递产品的价值&quot;">​</a></h2><p>相信现在，你也发现了洞察客户的需求与感知偏好以及对产品本身的设计都是非常重要的。今天我要分享的 5D 模型，就是基于这个逻辑总结的。</p><p>不过在详细讲解之前，你还要理解 5D 模型的两个关键理念：</p><ol><li><p>以客户为中心。</p></li><li><p>所有事都应该看作一件事。</p></li></ol><h3 id="什么是-以客户为中心" tabindex="-1">什么是“以客户为中心”？ <a class="header-anchor" href="#什么是-以客户为中心" aria-label="Permalink to &quot;什么是“以客户为中心”？&quot;">​</a></h3><p>你应该经常听到以用户为中心这个概念，但真正执行到位的产品并不多。</p><p>我举个例子，CRM（客户关系管理）行业巨头 Salesforce 发生过一次重大的信息安全事故。要知道作为 SaaS 企业，客户最不放心的就是企业信息放在云服务器上发生危险。</p><p>修复问题后，当时的 CEO 马克·贝尼奥夫不仅没规避问题，还实施了一个大胆的计划，将Salesforce 的安全情况进行实时公布，推出了 status.salesforce.com 项目，将 Salesforce 每分每秒的信息安全情况实时公布给所有人。这个举措为他赢得了客户的信任与尊重。直到现在，这些安全信息每天都在对外公布。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/B%E7%AB%AF%E4%BD%93%E9%AA%8C%E8%AE%BE%E8%AE%A1%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/2.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/B%E7%AB%AF%E4%BD%93%E9%AA%8C%E8%AE%BE%E8%AE%A1%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/2.jpeg" alt=""></a></p><p>所以，真正的以客户为中心，不是说说而已，而是落实到产品团队的每一个行为、每一个功能中。</p><h3 id="为什么所有事都该看作一件事" tabindex="-1">为什么所有事都该看作一件事？ <a class="header-anchor" href="#为什么所有事都该看作一件事" aria-label="Permalink to &quot;为什么所有事都该看作一件事？&quot;">​</a></h3><p>正如我们开篇词所说，当你在优化 B 端产品的时候，需要重塑对体验的理解。要记住，客户找不到功能、用得不顺畅，甚至觉得文案不懂，都是体验问题。反过来看，当你在做产品功能规划、功能归类、产品流程设计的时候，都必须要基于“以客户为中心”的理念去设计，因为这些都是产品体验的一部分。</p><p>在 B 端产品中，体验不再只是界面点击是否顺畅、动画效果是否酷炫这些问题，借用 SaaS的概念，整个产品都应看做服务体验。</p><p>所以当你在设计 B 端产品的时候，要把每一件事都看作是在做体验设计。</p><h3 id="_5d-产品设计体系" tabindex="-1">5D 产品设计体系 <a class="header-anchor" href="#_5d-产品设计体系" aria-label="Permalink to &quot;5D 产品设计体系&quot;">​</a></h3><p>想落实这两个理念，就离不开一个合适、完整的设计步骤。相信你也了解过“双钻模型”，但它在 B 端的应用方式有非常多的不同，5D 模型就是我基于双钻模型衍生出来的一套完整的 B 端设计方法。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/B%E7%AB%AF%E4%BD%93%E9%AA%8C%E8%AE%BE%E8%AE%A1%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/B%E7%AB%AF%E4%BD%93%E9%AA%8C%E8%AE%BE%E8%AE%A1%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/3.png" alt=""></a></p><p>接下来，我会给你讲解“5D 产品设计体系”中每一个阶段的作用，至于具体的实现方式，都会在后面的课程中通过“方法 + 案例”的形式为你详细讲解。</p><ul><li>Discover：发现价值信息</li></ul><p>5D 模型的第一步是收集信息，并且挖掘有价值的内容。</p><p>在 B 端行业中，这一步难如登天。因为客户非常难邀约，有时候拜访一个客户需要等 2 小时、甚至 2、3 天的时间，有的 B 端设计师甚至没有接触到客户的机会。但在以客户为中心的理念下，了解客户信息与偏好是必要的一步，所以我们通过了 3 年的实践，找到了更高维度的方法。</p><p>在无法接触客户的情况下，需要应用更底层的心理学方法来进行分析与洞察，找到客户的动机，还有影响客户潜意识的因素。</p><p>具体来说，就是通过了解客户所在的岗位职责要求，了解他们的“利益动机”，再了解他们每天使用的产品与工作环境，了解他们对于习惯的底层认知，才能做到在只接触几个客户的情况下，就洞察出有效的用户研究结果，为体验设计提供明确的方向与信息。</p><ul><li>Define：定义需求与体验设计方向</li></ul><p>这一步需要我们分享收集到的大量信息，并且发现有价值的内容。特别是在 B 端领域中，信息量非常大，有收集到的业务信息，也有客户杂乱的需求，还有公司内部大家的意见，这就导致很多同学不知道怎么整理信息。</p><p>如果你是一个刚入门的小白，可能经常会陷入被动接收大量信息的状态，让自己手忙脚乱。这个阶段，就需要建立一套判断信息价值的标准，梳理信息的优先级与脉络。这里有一个技巧，就是找到客户在业务方面的“利益动机”。</p><p>比如在 CRM 产品里，执行岗位关注的是能不能快点干完工作，所以在面向这类群体时，客户信息录入与查看功能的操作效率就显得尤其重要；而管理岗位关注的是工作的质量和成本，那是不是设计上需要更多类似统计报表、趋势分析的功能？</p><p>不管是什么岗位，只要和利益动机相关的内容，都应该重点关注，多花时间深入研究。因为这些最有价值的信息直接影响了客户的最终感受。而在与利益动机无关的内容上，就可以少花时间了。</p><p>如果你是一个已经入门了一段时间的 B 端设计师，就更要总结出与业务相关的内容。比如，这个产品所服务的业务上下游有哪些？为什么这个产品在业务协作中不可替代？通过总结业务相关的要点信息，你就可以找到体验设计和以后改版优化应该发挥的方向。</p><p>如果你已经是一个从业 5 年以上的 B 端设计师，那就应该站到更高的角度看问题，主动走到业务深处。多关注行业中新技术的应用以及其他产品的发展情况，总结是否有新的巨大变革。就像现在 AIGC 可以替代人类画图这类颠覆性创新一样，从中洞察到行业的发展趋势，预判产品未来 1-3 年可能的发展方向，找出在体验设计中应该提前预备的内容，帮助产品在后续的竞争中通过优秀的体验获得竞争优势。</p><p>当然，这也是一个你自己成长的过程，在定义出体验设计方向的过程中，也要考虑到自己的能力建设与职业发展。通过锻炼利益动机分析、业务分析、行业发展分析的能力，让自己在企业中的商业价值也越来越高。</p><ul><li>Design：设计体验内容</li></ul><p>产品体验的设计是需要从用户使用整个产品的流程来考虑的。以客户第一次看到产品为起点，到客户最终不再使用产品为终点，客户在产品中的整个过程可以称为“全生命周期”。</p><p>在这个过程中，从注册账号、寻找功能入口开始，到每天的使用过程以及定期的续费过程，都要考虑进来。记住，要把整个客户生命周期的体验都看作是产品的体验，因为客户视角中，只有整个产品体验的好坏，没有某个环节的体验好坏。</p><ul><li>Development：研发落地</li></ul><p>在这个过程中，最重要的是保障落地实施的效果。</p><p>因为客户使用的不是你的设计效果图，所以你必须要守好落地实施的最后一公里，不然前面所有的心血就白费了。</p><p>想要拥有一个好的落地效果，首先，你需要清楚地澄清你的需求、设计内容，以标准且清晰的文档形式交付给你的开发同事，并且建立一个稳定的团队合作机制，才能真正保障你的产品最终在客户面前具备一个优秀的体验。</p><p>特别是在 B 端产品中，涉及的功能与界面数量大部分是 C 端产品的好几倍，并且很多团队会觉得功能可以做出来就不错了，不太关心界面最终的呈现效果，导致了体验下滑。所以在 B端产品中，一定要在最终研发落地的时候多花时间，甚至花一周时间，坐到开发同事的身边一起调整，才能保障最终的落地效果。</p><ul><li>Update：体验迭代，客户的要求永远都会更多</li></ul><p>最后，你要明白客户的需求是无限的。他们在使用了产品后一定会产生更多的需求，所以你必须要基于客户的新需求进行新的产品体验设计，这个过程通常叫做“迭代”。</p><p>由于面向的客户群体不同，B 端产品的迭代会比 C 端更复杂。因为 C 端客户面向的是单体用户，所以通常用户提出的新需求都会比较类似，但 B 端面向的是多个不同需求的群体，所以提出新需求的方向与内容都会比 C 端多很多，并且客户又难以接触到。</p><p>所以在迭代的过程中，有两点你必须要注意。</p><p>第一，是要保障有持续收集客户反馈的渠道，千万不要陷入自己团队臆想的状态中去。</p><p>第二，是提前进行规划。大部分产品在开发过程中都不是完美的，有很多体验问题可以预判到，你要尽早想清楚这些问题的后续解决方案，这个可能为你的产品迭代省下上百万的成本，并且还能获得客户的好评。</p><h2 id="b-端设计师的核心能力进阶" tabindex="-1">B 端设计师的核心能力进阶 <a class="header-anchor" href="#b-端设计师的核心能力进阶" aria-label="Permalink to &quot;B 端设计师的核心能力进阶&quot;">​</a></h2><p>5D 模型是一种体验设计的思维框架。但是应用的时候，特别是在 B 端领域的体验设计中，难以接触客户这个问题让大家一开始就止步了。所以，B 端体验设计的思维可以更往前一步，深入到业务，理解产品整体规划与业务的关系，不能再局限于只关注界面的设计与美感。这样。我们才能真正成为一个优秀的体验设计师。</p><p>在这期间，你也一定会遇到很多职业发展问题，是应该先学方法论，还是先学设计技巧呢？</p><p>我总结了 B 端体验设计师能力模型，帮助你了解各个阶段体验设计师的主要能力指标。这套能力的最终目标是帮助企业打造出客户喜爱并且愿意持续购买的产品，一共有五个阶段。</p><ul><li>1-3 年阶段，注重执行能力</li></ul><p>这个阶段你需要注重的是执行能力，能够基于产品和行业的规范，高效、高质量地输出设计内容，通常输出的都是次要的界面与组件。</p><ul><li>3-5 年阶段，注重“传递价值”的设计能力</li></ul><p>这个阶段你需要在高效执行的基础上进行升级，能更好地进行主要界面体验的创新。这就要求你能准确地洞察到客户的需求与体验偏好，并且可以通过体验设计，让客户准确感受到产品想要传递的价值。</p><ul><li>5-8 年的阶段，注重逻辑整体构架的能力</li></ul><p>在这个阶段，你需要具备对业务深度理解的能力。在这个过程中，能预判产品未来一段时间的发展情况，并且需要具备信息构架与构建有效组件体系的能力。</p><ul><li>8 年以上，注重分析能力与洞察力</li></ul><p>当你从事了较长时间的 B 端体验设计时，最终需要锻炼的一个能力，就是通过洞察客户真实的诉求与偏好。通过体验设计保障一件事，那就是即便产品的售价比同行的相对较高，但客户却更愿意选择我们的产品。</p><p>这个挑战看似很大，但回顾一下你身边购买过的产品，有的用户会选择上千元的 iPhone、华为等，但不会选择六七百的红米手机。实际上，手机的功能基本一样，但最终选择的是一个体验更好，但价格贵了 5-10 倍的产品。</p><p>所以，作为一个资深的体验设计师，在以商业形式运作的企业中，你需要通过为客户提供更优质的产品与服务，让客户主动地、持续地购买你的产品，帮助客户，甚至自己达成更好的商业目标。</p><p>当然，工作年份只是一个参考，我见过很多伙伴，在正确的方向上，付出了双倍的努力，在 3年就拥有了 5 年的能力，只要尽早找好方向，坚持学习，你也可以做到。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/B%E7%AB%AF%E4%BD%93%E9%AA%8C%E8%AE%BE%E8%AE%A1%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/4.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/B%E7%AB%AF%E4%BD%93%E9%AA%8C%E8%AE%BE%E8%AE%A1%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/4.jpeg" alt=""></a></p><h2 id="总结时刻" tabindex="-1">总结时刻 <a class="header-anchor" href="#总结时刻" aria-label="Permalink to &quot;总结时刻&quot;">​</a></h2><p>学习完这节课，我希望你能深刻理解到体验设计的价值，是传递甚至放大企业产品或服务价值的必要方法。而要想让设计落地，就需要一个完整、契合的设计流程。这也是会贯穿我们整套课程的“5D 产品设计体系”。</p><ul><li><p>发现（Discover）：发现价值信息，包括用户自身信息、偏好等。</p></li><li><p>定义（Define）：收拢信息，梳理需求，定义需求与体验设计方向。</p></li><li><p>设计（Design）：以整个产品的流程（全生命周期）设计体验内容。</p></li><li><p>开发（Development）：保障研发落地的实施效果。</p></li><li><p>迭代（Update）：保障有持续收集客户反馈的渠道，提前为后续问题设计解决方案。</p></li></ul><p>在 5D 模型的基础上，也就有了 B 端体验设计师职业成长的 4 个阶段。没有人一开始就能完美落地整个流程，方向不清楚的时候，不妨给自己设个阶段目标，比如 1-3 年偏重执行落地，到3-5 年偏重核心内容设计，再到 5-8 年注重整体构架能力，以及 8 年以上注重分析与洞察力。</p><p>除了这些知识点，我还希望你能通过这些方法，少走很多弯路。我见过一些设计师，非常努力，经常加班，但工作了八年，依然只拥有三年的能力。希望你能理解到“认知决定上限”的理念，一定要多去打开自己的视野，了解行业中优秀的方法，才能保障自己在正确的方向上，不然很容易浪费大好年华。</p><p>相信通过这两节课，已经能够帮助你重塑对于 B 端体验设计的认知。下节课，我们就进入正式的方法学习，期待与你共同成长。</p><h2 id="解惑-tob-体验设计" tabindex="-1">解惑 ToB 体验设计 <a class="header-anchor" href="#解惑-tob-体验设计" aria-label="Permalink to &quot;解惑 ToB 体验设计&quot;">​</a></h2><p>你认为 B 端体验设计师最重要的能力是什么呢？</p><p>欢迎你在留言区和我互动。如果觉得有所收获，也欢迎你把课程分享给更多的朋友一起交流进步，我们下一讲见！</p>',87)])])}const u=i(a,[["render",n]]);export{A as __pageData,u as default};
